export type ChartSeries = { id: string; name: string; color: string };
export type ChartRow = { t: number } & Record<string, number | null>;
export type TimelineState = { className: string; label: string };

/** The states a timeline knows by default. Pass `states` for an app's own words. */
export const DEFAULT_TIMELINE_STATES: Record<string, TimelineState> = {
  running: { className: "bg-online", label: "Up" },
  starting: { className: "bg-warn/60", label: "Starting" },
  reconnecting: { className: "bg-warn", label: "Retrying" },
  failed: { className: "bg-danger", label: "Failed" },
};

import type { EChartsCoreOption } from "echarts/core";
import { clockTime, timeTicks } from "@/ui/chart-format";
import type { ChartRow, ChartSeries } from "@/ui/chart-types";

/** Resolved theme colours, read from the CSS variables by the component so this stays pure. */
export type TimeChartTheme = {
  text: string;
  grid: string;
  tooltipText: string;
};

export type TimeChartInput = {
  rows: ChartRow[];
  series: ChartSeries[];
  from: number;
  to: number;
  format: (v: number) => string;
  formatAxis?: (v: number) => string;
  reference?: { value: number; label: string }[];
  theme: TimeChartTheme;
};

const escapeHtml = (text: string) => text.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

/** Gap in px between the pointer and the tooltip box, as Recharts places it. */
const TOOLTIP_OFFSET = 10;

/**
 * Recharts' placement: the box sits 10px right of and below the pointer, flips to the left when it
 * would pass the chart's right edge, and is kept inside the chart.
 */
export function tooltipPosition(
  point: number[],
  _params: unknown,
  _dom: unknown,
  _rect: unknown,
  size: { contentSize: number[]; viewSize: number[] },
): [number, number] {
  const [width, height] = size.contentSize;
  const [viewWidth, viewHeight] = size.viewSize;
  const right = point[0] + TOOLTIP_OFFSET;
  const x = right + width > viewWidth ? point[0] - TOOLTIP_OFFSET - width : right;
  const y = point[1] + TOOLTIP_OFFSET;
  return [
    Math.max(0, Math.min(x, viewWidth - width)),
    Math.max(0, Math.min(y, viewHeight - height)),
  ];
}

/** Crosshair tooltip content, the React `ChartTooltip` markup: the time, then a row per series. */
function tooltipHtml(
  ts: number,
  entries: { series: ChartSeries; value: number }[],
  format: (v: number) => string,
): string {
  if (entries.length === 0) return "";
  const lines = entries
    .map(
      ({ series, value }) =>
        `<div class="flex items-center gap-2">` +
        `<span class="size-2 shrink-0 rounded-sm" style="background-color:${escapeHtml(series.color)}" aria-hidden="true"></span>` +
        `<span class="min-w-0 flex-1 truncate text-muted-foreground">${escapeHtml(series.name)}</span>` +
        `<span class="font-mono tabular-nums">${escapeHtml(format(value))}</span>` +
        `</div>`,
    )
    .join("");
  return (
    `<div class="rounded-md bg-popover px-2.5 py-2 text-xs shadow-[var(--shadow-elevated)]">` +
    `<div class="mb-1 font-mono text-[11px] text-muted-foreground">${clockTime(ts)}</div>` +
    `<div class="grid gap-1">${lines}</div></div>`
  );
}

/** Whether any series has a non-null value in any row; otherwise the chart shows its empty label. */
export function hasChartData(rows: ChartRow[], series: ChartSeries[]): boolean {
  return rows.some((row) => series.some((item) => row[item.id] != null));
}

/**
 * The ECharts option for a time chart. A null value (or a missing key) stays null in the
 * data and the line is not connected across it: that is a gap, not a zero.
 */
export function buildTimeChartOption(input: TimeChartInput): EChartsCoreOption {
  const { rows, series, from, to, format, reference = [], theme } = input;
  const formatAxis = input.formatAxis ?? format;
  const axis = timeTicks(from, to);
  const refMax = reference.length ? Math.max(...reference.map((line) => line.value)) : null;

  const lines = series.map((item, index) => ({
    id: item.id,
    name: item.name,
    type: "line" as const,
    data: rows.map((row) => [row.t, row[item.id] ?? null] as [number, number | null]),
    connectNulls: false,
    // The hover dot (Recharts activeDot r=4): hidden at rest, shown by the axis tooltip.
    showSymbol: false,
    symbol: "circle",
    symbolSize: 8,
    emphasis: { scale: false },
    animation: false,
    lineStyle: { color: item.color, width: 2 },
    itemStyle: { color: item.color, borderColor: "#12141a", borderWidth: 2 },
    ...(index === 0 && reference.length
      ? {
          markLine: {
            silent: true,
            symbol: "none",
            animation: false,
            lineStyle: { color: theme.text, type: [4, 4] as number[], width: 1 },
            data: reference.map((line) => ({
              yAxis: line.value,
              label: {
                formatter: line.label,
                position: "insideEndTop" as const,
                color: theme.text,
                fontSize: 10,
              },
            })),
          },
        }
      : {}),
  }));

  return {
    animation: false,
    grid: { top: 8, right: 20, bottom: 0, left: 0, containLabel: true },
    xAxis: {
      type: "time",
      min: from,
      max: to,
      axisLine: { lineStyle: { color: theme.grid } },
      axisTick: { show: false, customValues: axis.ticks },
      splitLine: { show: false },
      axisLabel: {
        color: theme.text,
        fontSize: 11,
        hideOverlap: true,
        customValues: axis.ticks,
        formatter: (value: number) => clockTime(value, axis.withSeconds),
      },
    },
    yAxis: {
      type: "value",
      min: 0,
      // A reference line above the data still has to be inside the plot.
      ...(refMax == null ? {} : { max: (v: { max: number }) => Math.max(v.max, refMax) }),
      axisLine: { show: false },
      axisTick: { show: false },
      splitLine: { lineStyle: { color: theme.grid } },
      axisLabel: { color: theme.text, fontSize: 11, formatter: (v: number) => formatAxis(v) },
    },
    tooltip: {
      trigger: "axis",
      // The box is drawn by the formatter; ECharts' own chrome is switched off.
      backgroundColor: "transparent",
      borderWidth: 0,
      padding: 0,
      confine: true,
      transitionDuration: 0,
      textStyle: { color: theme.tooltipText },
      extraCssText: "box-shadow: none;",
      position: tooltipPosition,
      axisPointer: {
        type: "line",
        lineStyle: { color: "rgb(236 238 242 / 25%)", width: 1, type: "solid" },
      },
      formatter: (params: unknown) => {
        const list = (Array.isArray(params) ? params : [params]) as {
          seriesId?: string;
          value?: [number, number | null];
        }[];
        if (list.length === 0 || !list[0].value) return "";
        const entries = series.flatMap((item) => {
          const hit = list.find((p) => p.seriesId === item.id);
          const value = hit?.value?.[1];
          return value == null ? [] : [{ series: item, value }];
        });
        return tooltipHtml(list[0].value[0], entries, format);
      },
    },
    series: lines,
  };
}

import { describe, expect, it } from "vitest";
import type { ChartRow, ChartSeries } from "@/ui/chart-types";
import { timeTicks } from "@/ui/chart-format";
import {
  buildTimeChartOption,
  hasChartData,
  tooltipPosition,
  type TimeChartTheme,
} from "@/ui/time-chart-options";

const theme: TimeChartTheme = {
  text: "#8b909c",
  grid: "rgba(236,238,242,0.08)",
  tooltipText: "#eceef2",
};
const series: ChartSeries[] = [
  { id: "cpu", name: "CPU", color: "#3987e5" },
  { id: "mem", name: "Memory", color: "#d95926" },
];
const rows: ChartRow[] = [
  { t: 1000, cpu: 10, mem: 20 },
  { t: 2000, cpu: null, mem: 30 },
  { t: 3000, cpu: 12, mem: 40 },
];
const base = { rows, series, from: 1000, to: 3000, format: (v: number) => `${v}%`, theme };

type Opt = {
  xAxis: { type: string; min: number; max: number };
  series: {
    type: string;
    data: [number, number | null][];
    connectNulls: boolean;
    showSymbol: boolean;
    lineStyle: { color: string };
    areaStyle?: unknown;
    markLine?: { data: { yAxis: number }[] };
  }[];
};
const build = (extra = {}) => buildTimeChartOption({ ...base, ...extra }) as unknown as Opt;

describe("buildTimeChartOption", () => {
  it("makes one line per series with its colour", () => {
    const option = build();
    expect(option.series.map((s) => s.type)).toEqual(["line", "line"]);
    expect(option.series.map((s) => s.lineStyle.color)).toEqual(["#3987e5", "#d95926"]);
    expect(option.series.every((s) => s.showSymbol === false)).toBe(true);
  });

  it("keeps null in the data and does not connect across it", () => {
    const [cpu] = build().series;
    expect(cpu.data).toEqual([
      [1000, 10],
      [2000, null],
      [3000, 12],
    ]);
    expect(build().series.every((s) => s.connectNulls === false)).toBe(true);
  });

  it("treats a missing key as a gap", () => {
    const option = build({ rows: [{ t: 1, cpu: 1 } as ChartRow] });
    expect(option.series[1].data).toEqual([[1, null]]);
  });

  it("builds from empty rows without throwing", () => {
    const option = build({ rows: [] });
    expect(option.series.map((s) => s.data)).toEqual([[], []]);
  });

  it("draws no area under the lines", () => {
    expect(build().series.some((s) => s.areaStyle)).toBe(false);
  });

  it("turns a reference into a markLine at its value", () => {
    const [cpu, mem] = build({ reference: [{ value: 80, label: "Limit" }] }).series;
    expect(cpu.markLine?.data).toEqual([expect.objectContaining({ yAxis: 80 })]);
    expect(mem.markLine).toBeUndefined();
  });

  it("pins the time axis to from and to", () => {
    const { xAxis } = build();
    expect(xAxis.type).toBe("time");
    expect([xAxis.min, xAxis.max]).toEqual([1000, 3000]);
  });
});

describe("hasChartData", () => {
  it("is false for empty rows", () => {
    expect(hasChartData([], series)).toBe(false);
  });

  it("is false when every value is null or missing", () => {
    expect(hasChartData([{ t: 1, cpu: null, mem: null }, { t: 2 } as ChartRow], series)).toBe(
      false,
    );
  });

  it("is true with one non-null value, including zero", () => {
    expect(hasChartData([{ t: 1, cpu: null, mem: 0 }], series)).toBe(true);
  });

  it("ignores keys that are not a series", () => {
    expect(hasChartData([{ t: 1, other: 5 }], series)).toBe(false);
  });
});

describe("chart hover styling", () => {
  type Tip = {
    confine: boolean;
    transitionDuration: number;
    padding: number;
    position: typeof tooltipPosition;
    axisPointer: { type: string; lineStyle: { color: string; width: number; type: string } };
  };
  const tip = () => (build() as unknown as { tooltip: Tip }).tooltip;

  it("draws a 1px solid crosshair in the React colour", () => {
    expect(tip().axisPointer).toEqual({
      type: "line",
      lineStyle: { color: "rgb(236 238 242 / 25%)", width: 1, type: "solid" },
    });
  });

  it("gives each series an r=4 hover dot with a dark border that does not scale", () => {
    for (const s of build().series as unknown as {
      symbol: string;
      symbolSize: number;
      itemStyle: { borderColor: string; borderWidth: number };
      emphasis: { scale: boolean };
    }[]) {
      expect(s.symbol).toBe("circle");
      expect(s.symbolSize).toBe(8);
      expect(s.itemStyle).toMatchObject({ borderColor: "#12141a", borderWidth: 2 });
      expect(s.emphasis.scale).toBe(false);
    }
  });

  it("keeps the tooltip instant, confined and unframed", () => {
    expect(tip()).toMatchObject({ confine: true, transitionDuration: 0, padding: 0 });
  });

  it("places the tooltip 10px right of the pointer and flips left near the edge", () => {
    const size = { contentSize: [100, 50], viewSize: [400, 200] };
    expect(tip().position([100, 40], null, null, null, size)).toEqual([110, 50]);
    expect(tip().position([300, 40], null, null, null, size)).toEqual([190, 50]);
    expect(tip().position([100, 190], null, null, null, size)).toEqual([110, 150]);
  });
});

describe("x axis ticks", () => {
  it("uses the explicit React ticks for labels and tick marks", () => {
    const from = 1_700_000_000_000;
    const to = from + 15 * 60_000;
    const option = buildTimeChartOption({ ...base, from, to }) as unknown as {
      xAxis: { axisLabel: { customValues: number[] }; axisTick: { customValues: number[] } };
    };
    const { ticks } = timeTicks(from, to);
    expect(option.xAxis.axisLabel.customValues).toEqual(ticks);
    expect(option.xAxis.axisTick.customValues).toEqual(ticks);
  });
});

/**
 * The point lists of a sparkline, one per run between nulls (a null breaks the line).
 * A lone point between gaps is a single-point run. X spreads over `width`; Y scales to
 * the largest value (at least 1) with a 2px margin.
 */
export function sparklineSegments(
  values: (number | null)[],
  width: number,
  height: number,
): [number, number][][] {
  const present = values.filter((value): value is number => value != null);
  const max = Math.max(...present, 1);
  const step = width / Math.max(1, values.length - 1);
  const runs: [number, number][][] = [];
  let drawing = false;
  values.forEach((value, index) => {
    if (value == null) {
      drawing = false;
      return;
    }
    if (!drawing) runs.push([]);
    runs[runs.length - 1].push([index * step, height - 2 - (value / max) * (height - 4)]);
    drawing = true;
  });
  return runs;
}

import { describe, expect, it } from "vitest";
import { sparklineSegments } from "@/ui/sparkline-geometry";

describe("sparklineSegments", () => {
  it("draws one run for unbroken values", () => {
    const runs = sparklineSegments([1, 2, 3], 72, 20);
    expect(runs).toHaveLength(1);
    expect(runs[0]).toHaveLength(3);
    expect(runs[0][0][0]).toBe(0);
    expect(runs[0][2][0]).toBe(72);
  });

  it("splits at nulls", () => {
    const runs = sparklineSegments([30, 28, null, null, 6, 2], 72, 20);
    expect(runs.map((run) => run.length)).toEqual([2, 2]);
  });

  it("gives a lone point between gaps a single-point run", () => {
    const runs = sparklineSegments([5, null, 7, null, 9, 9], 72, 20);
    expect(runs.map((run) => run.length)).toEqual([1, 1, 2]);
  });

  it("puts the largest value at the top margin and zero at the bottom", () => {
    const [run] = sparklineSegments([0, 10], 72, 20);
    expect(run[0][1]).toBe(18);
    expect(run[1][1]).toBe(2);
  });

  it("returns no runs for all nulls", () => {
    expect(sparklineSegments([null, null], 72, 20)).toEqual([]);
  });
});

import { ChangeDetectionStrategy, Component, computed, input } from "@angular/core";
import { sparklineSegments } from "@/ui/sparkline-geometry";
import { cn } from "@/ui/utils";

const WIDTH = 72;
const HEIGHT = 20;

/** Point lists for the runs between nulls; a lone point is drawn as a zero-length stroke. */
function segments(values: (number | null)[]): string[] {
  return sparklineSegments(values, WIDTH, HEIGHT).map((run) => {
    const points = run.map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`);
    return points.length === 1 ? `${points[0]} ${points[0]}` : points.join(" ");
  });
}

/**
 * A tiny trend line for a table cell, drawn as plain SVG. A null value breaks the
 * line: the thing was not running then. The cell's number beside it is the value;
 * this only shows whether it has been steady.
 */
@Component({
  selector: "ko-sparkline",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[class]": "classes()", "[attr.aria-hidden]": "drawable() ? null : 'true'" },
  template: `
    @if (drawable()) {
      <svg
        width="72"
        height="20"
        viewBox="0 0 72 20"
        role="img"
        [attr.aria-label]="label()"
        class="block"
      >
        <title>{{ label() }}</title>
        @for (points of runs(); track $index) {
          <polyline
            [attr.points]="points"
            fill="none"
            stroke="currentColor"
            stroke-width="1.5"
            stroke-linejoin="round"
            stroke-linecap="round"
          />
        }
      </svg>
    }
  `,
})
export class KoSparkline {
  readonly values = input.required<(number | null)[]>();
  readonly label = input.required<string>();
  readonly class = input<string>("");

  protected readonly drawable = computed(
    () => this.values().filter((value) => value != null).length >= 2,
  );
  protected readonly runs = computed(() => (this.drawable() ? segments(this.values()) : []));
  protected readonly classes = computed(() =>
    cn("inline-block h-5 w-[72px] shrink-0", this.drawable() && "text-signal", this.class()),
  );
}

import { ChangeDetectionStrategy, Component, computed, input } from "@angular/core";
import { clockTime } from "@/ui/chart-format";
import { DEFAULT_TIMELINE_STATES, type TimelineState } from "@/ui/chart-types";
import { cn } from "@/ui/utils";

type Block = { state: string; start: number; end: number };
type TimelineRow = { id: string; name: string; states: (string | null)[] };

/**
 * One strip per item: up, retrying or failed over the range. Steps with
 * the same state are merged into one block, and hovering a block gives its times.
 */
@Component({
  selector: "ko-state-timeline",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[attr.title]": "null", "[class]": "classes()" },
  template: `
    <div class="mb-3 flex flex-wrap items-center justify-between gap-x-4 gap-y-1">
      <h3 class="text-sm font-medium">{{ title() }}</h3>
      <ul class="flex flex-wrap gap-x-3 gap-y-1 text-[11px] text-muted-foreground">
        @for (entry of legend(); track entry.state) {
          <li class="flex items-center gap-1.5">
            <span [class]="swatch(entry.tone.className)" aria-hidden="true"></span>
            {{ entry.tone.label }}
          </li>
        }
        <li class="flex items-center gap-1.5">
          <span
            class="size-2 rounded-sm bg-inset shadow-[var(--shadow-border)]"
            aria-hidden="true"
          ></span>
          {{ idleLabel() }}
        </li>
      </ul>
    </div>
    <div class="grid gap-2">
      @for (row of strips(); track row.id) {
        <div class="grid grid-cols-[minmax(0,10rem)_minmax(0,1fr)] items-center gap-3">
          <span class="truncate text-xs text-muted-foreground">{{ row.name }}</span>
          <div
            class="relative h-3 overflow-hidden rounded-sm bg-inset shadow-[var(--shadow-border)]"
          >
            @for (block of row.blocks; track block.start) {
              <span
                [attr.title]="block.title"
                [class]="block.classes"
                [style.left]="block.left"
                [style.width]="block.width"
              ></span>
            }
          </div>
        </div>
      }
    </div>
    <div
      class="mt-2 grid grid-cols-[minmax(0,10rem)_minmax(0,1fr)] gap-3 font-mono text-[10px] text-muted-foreground"
    >
      <span></span>
      <span class="flex justify-between">
        <span>{{ fromLabel() }}</span>
        <span>{{ toLabel() }}</span>
      </span>
    </div>
  `,
})
export class KoStateTimeline {
  readonly title = input<string>("State");
  /** One state per step of `stepMs` from `from`; null where there was nothing. */
  readonly rows = input.required<TimelineRow[]>();
  readonly from = input.required<number>();
  readonly to = input.required<number>();
  readonly stepMs = input.required<number>();
  /** Colour and legend word per state. A state not listed is drawn grey under its own name. */
  readonly states = input<Record<string, TimelineState>>(DEFAULT_TIMELINE_STATES);
  readonly idleLabel = input<string>("Not running");
  readonly class = input<string>("");

  protected readonly fromLabel = computed(() => clockTime(this.from(), false));
  protected readonly toLabel = computed(() => clockTime(this.to(), false));
  protected readonly classes = computed(() =>
    cn("block rounded-xl bg-card p-4 shadow-[var(--shadow-border)]", this.class()),
  );
  protected readonly legend = computed(() =>
    Object.entries(this.states()).map(([state, tone]) => ({ state, tone })),
  );

  protected swatch(className: string): string {
    return cn("size-2 rounded-sm", className);
  }

  protected readonly strips = computed(() => {
    const from = this.from();
    const to = this.to();
    const stepMs = this.stepMs();
    const states = this.states();
    const span = Math.max(1, to - from);
    return this.rows().map((row) => {
      const blocks: Block[] = [];
      row.states.forEach((state, index) => {
        if (!state) return;
        const start = from + index * stepMs;
        const last = blocks[blocks.length - 1];
        if (last && last.state === state && last.end === start) {
          last.end = start + stepMs;
        } else {
          blocks.push({ state, start, end: start + stepMs });
        }
      });
      return {
        id: row.id,
        name: row.name,
        blocks: blocks.map((block) => {
          const tone = states[block.state] ?? { className: "bg-offline", label: block.state };
          return {
            start: block.start,
            classes: cn("absolute inset-y-0", tone.className),
            title: `${tone.label} · ${clockTime(block.start)} to ${clockTime(Math.min(block.end, to))}`,
            left: `${((block.start - from) / span) * 100}%`,
            width: `${Math.max(0.3, ((block.end - block.start) / span) * 100)}%`,
          };
        }),
      };
    });
  });
}

import {
  afterNextRender,
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  ElementRef,
  inject,
  input,
  signal,
} from "@angular/core";
import { NgIcon } from "@ng-icons/core";
import { LineChart } from "echarts/charts";
import { GridComponent, MarkLineComponent, TooltipComponent } from "echarts/components";
import * as echarts from "echarts/core";
import { CanvasRenderer } from "echarts/renderers";
import { NgxEchartsDirective, provideEchartsCore } from "ngx-echarts";
import type { ChartRow, ChartSeries } from "@/ui/chart-types";
import { buildTimeChartOption, hasChartData, type TimeChartTheme } from "@/ui/time-chart-options";
import { cn } from "@/ui/utils";

echarts.use([LineChart, GridComponent, TooltipComponent, MarkLineComponent, CanvasRenderer]);

/**
 * A line chart over time with one line per series, in the frame Pylon's metric panels
 * use. The legend is always shown for two or more series and carries each one's latest
 * value, so nothing has to be read off the tooltip.
 */
@Component({
  selector: "ko-time-chart",
  imports: [NgIcon, NgxEchartsDirective],
  providers: [provideEchartsCore({ echarts })],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[attr.title]": "null", "[class]": "classes()" },
  template: `
    <div class="mb-3 flex items-start gap-2">
      <span class="mt-0.5 shrink-0 text-muted-foreground">
        <ng-icon aria-hidden="true" size="16px" [svg]="icon()" />
      </span>
      <div class="min-w-0 flex-1">
        <h3 class="truncate text-sm font-medium">{{ title() }}</h3>
        @if (description()) {
          <p class="truncate text-xs text-muted-foreground">{{ description() }}</p>
        }
      </div>
      @if (series().length === 1) {
        <span class="shrink-0 text-sm tabular-nums">{{ legend()[0].text }}</span>
      }
    </div>
    @if (series().length > 1) {
      <ul class="mb-2 flex flex-wrap gap-x-4 gap-y-1 text-xs">
        @for (item of legend(); track item.id) {
          <li class="flex min-w-0 items-center gap-1.5">
            <span
              class="size-2 shrink-0 rounded-sm"
              [style.background-color]="item.color"
              aria-hidden="true"
            ></span>
            <span class="truncate text-muted-foreground">{{ item.name }}</span>
            <span class="font-mono tabular-nums">{{ item.text }}</span>
          </li>
        }
      </ul>
    }
    <div [class]="plotClasses()" role="img" [attr.aria-label]="title() + ' over time'">
      @if (!hasData()) {
        <div
          class="absolute inset-0 grid place-items-center rounded-lg bg-inset text-xs text-muted-foreground"
        >
          {{ emptyLabel() }}
        </div>
      } @else if (option(); as chartOption) {
        <div echarts class="absolute inset-0" [options]="chartOption"></div>
      }
    </div>
  `,
})
export class KoTimeChart {
  readonly title = input.required<string>();
  /** An `@ng-icons/lucide` SVG string. */
  readonly icon = input.required<string>();
  readonly description = input<string>();
  readonly rows = input.required<ChartRow[]>();
  readonly series = input.required<ChartSeries[]>();
  readonly from = input.required<number>();
  readonly to = input.required<number>();
  readonly format = input.required<(value: number) => string>();
  readonly formatAxis = input<(value: number) => string>();
  /** Dashed horizontal lines for what a value is meant to be, such as the encoder target. */
  readonly reference = input<{ value: number; label: string }[]>();
  readonly emptyLabel = input<string>("No data");
  /** Layout only: the plot grows to the height its grid row gives the panel, and is never shorter than the fixed size. */
  readonly fill = input(false, { transform: booleanAttribute });
  readonly class = input<string>("");

  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;
  private readonly theme = signal<TimeChartTheme | null>(null);

  protected readonly classes = computed(() =>
    cn(
      "block min-w-0 rounded-xl bg-card p-4 shadow-[var(--shadow-border)]",
      this.fill() && "flex flex-col",
      this.class(),
    ),
  );
  protected readonly plotClasses = computed(() =>
    cn("relative", this.fill() ? "min-h-44 flex-1" : "h-44"),
  );

  protected readonly legend = computed(() => {
    const rows = this.rows();
    const format = this.format();
    return this.series().map((item) => {
      let value: number | null = null;
      for (let index = rows.length - 1; index >= 0 && value == null; index--) {
        value = rows[index][item.id] ?? null;
      }
      return { ...item, text: value == null ? "—" : format(value) };
    });
  });

  protected readonly hasData = computed(() => hasChartData(this.rows(), this.series()));

  /** Null until the browser has resolved the theme colours, so nothing is built on the server. */
  protected readonly option = computed(() => {
    const theme = this.theme();
    if (!theme) return null;
    return buildTimeChartOption({
      rows: this.rows(),
      series: this.series(),
      from: this.from(),
      to: this.to(),
      format: this.format(),
      formatAxis: this.formatAxis(),
      reference: this.reference(),
      theme,
    });
  });

  constructor() {
    afterNextRender(() => {
      const styles = getComputedStyle(this.host);
      const read = (name: string) => styles.getPropertyValue(name).trim();
      this.theme.set({
        text: read("--color-muted-foreground"),
        grid: read("--color-border"),
        tooltipText: read("--color-popover-foreground"),
      });
    });
  }
}

